<?php
declare(strict_types=1);
namespace App\Extensions\TitanGo\System\Presentation;
use App\Extensions\TitanGo\System\Contracts\GoProjectionPolicy;use App\Extensions\TitanGo\System\Contracts\GoProjectionProviderInterface;
final class GoPresentationService{public function __construct(private GoProjectionProviderInterface $projections){}public function today(string $company,string $worker):array{return$this->page('today',$this->projections->today($company,$worker),['field.today.summary','field.job.card']);}public function jobs(string $company,string $worker,array $filters=[]):array{return$this->page('jobs',$this->projections->jobs($company,$worker,$filters),['field.job.list']);}public function job(string $company,string $worker,string $job):array{return$this->page('job-detail',$this->projections->job($company,$worker,$job),['field.job.detail','field.evidence.capture','field.checklist']);}public function schedule(string $company,string $worker,array $range=[]):array{return$this->page('schedule',$this->projections->schedule($company,$worker,$range),['field.schedule']);}public function inbox(string $company,string $worker):array{return$this->page('inbox',$this->projections->inbox($company,$worker),['field.inbox']);}private function page(string $workspace,array $projection,array $components):array{GoProjectionPolicy::assertProjection($projection);return ['schema'=>'titan.apps.go.presentation.v1','surface'=>'go','workspace'=>$workspace,'projection'=>$projection,'presentation_intent'=>['semantic_components'=>$components,'actions_as_intents'=>true,'visual_treatment'=>'go.field.default']];}}
